import{_ as d,l as o,o as e,c as l,v as n,p as s,x as r,d as i,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"功耗墙与 Dennard 缩放","description":"","frontmatter":{"title":"功耗墙与 Dennard 缩放","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dennard-power-wall.md","filePath":"cs/dennard-power-wall.md","lastUpdated":1789023840000}'),A={name:"cs/dennard-power-wall.md"};function c(h,a,D,m,_,f){const t=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="功耗墙与-dennard-缩放" tabindex="-1">功耗墙与 Dennard 缩放 <a class="header-anchor" href="#功耗墙与-dennard-缩放" aria-label="Permalink to &quot;功耗墙与 Dennard 缩放&quot;">​</a></h1><div class="epigraph"><p>Dennard 缩放曾让电压与尺寸一起降，功耗密度近似不变；墙之后晶体管仍变多，瓦特不再跟面积成比例让出，频率停在墙上。</p><footer>—— 据 Dennard et al., Design of Ion-Implanted MOSFETs with Very Small Physical Dimensions, IEEE JSSC 1974；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/clock-gating-dvfs">上一课</a>给出门控与 DVFS。<a href="/cs/power-dynamic-static">动态与静态功耗</a>写了 \\(CV^2f\\)。缺口是历史约束：<strong>Dennard 缩放</strong>为何曾允许每代升高 \\(f\\)，以及功耗墙如何逼出多核与暗硅——否则摩尔课只剩晶体管计数口号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Dennard 等 1974：线性尺寸 \\(1/k\\)，电压 \\(1/k\\)，则电场大致不变，延迟降、功耗/器件降，\\(k^2\\) 倍密度下功耗密度近似恒定。缺口不是再推 \\(CV^2f\\)，而是：阈值电压不能按比例无限降（漏电指数上升），\\(V\\) 降不动则 \\(CV^2f\\) 在密度上升时把功耗密度顶破。频率不再每代自动涨，这就是功耗墙。</p><p>暗硅：同一时刻只能点亮部分芯片，否则无法散热。与把整片华莱士树每拍翻满相冲突——算术单元要可门控。</p><h3 id="功耗墙不是「摩尔定律死了」" tabindex="-1">功耗墙不是「摩尔定律死了」 <a class="header-anchor" href="#功耗墙不是「摩尔定律死了」" aria-label="Permalink to &quot;功耗墙不是「摩尔定律死了」&quot;">​</a></h3><p>晶体管密度仍可增（下一课经济学与工艺节点），只是<strong>性能/瓦</strong>的旧公式断了。把两句话当成同一句，会既说错 Dennard 也说错 Moore。多核、加速器、近存计算是墙之后的体系结构回答，本课只钉物理来源。</p><p><span class="marginnote">Dennard et al., <em>IEEE JSSC</em>, 1974。Esmaeilzadeh 等关于暗硅的论述在体系结构文献中广泛引用；CA:AQA 有功耗与多核转折的教材叙述。本课不发明 arXiv 号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照缩放表：理想 Dennard vs 后墙（\\(V\\) 近停滞、\\(f\\) 近停滞、\\(N\\) 仍增）。设计含义：并行度换吞吐、加速专用单元（FMA 阵列）只在使用时点亮、DVFS 在负载曲线上爬。STA 的目标频率由热设计功耗（TDP）封顶，不是由组合逻辑能跑多快单独决定。</p>',11)),(e(),s(p,null,{default:r(()=>[E(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEN%5B%22Dennard%EF%BC%9AV%20%E4%B8%8E%E5%B0%BA%E5%AF%B8%E5%90%8C%E9%99%8D%22%5D%20--%3E%20WALL%5B%22V%20%E5%81%9C%E3%80%81%E6%BC%8F%E7%94%B5%E3%80%81%E5%8A%9F%E8%80%97%E5%AF%86%E5%BA%A6%22%5D%0A%20%20WALL%20--%3E%20FREQ%5B%22%E9%A2%91%E7%8E%87%E5%A2%99%22%5D%0A%20%20FREQ%20--%3E%20PARA%5B%22%E5%B9%B6%E8%A1%8C%E4%B8%8E%E6%9A%97%E7%A1%85%22%5D%0A%20%20PARA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%91%A9%E5%B0%94%E7%BB%8F%E6%B5%8E%E5%AD%A6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>FPGA 同样受墙约束，LUT 翻转与静态漏电一起进 TDP。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课把「能不能继续缩小」改写成成本、良率与设计费用，而不是电场。本课给体系结构的约束：CPI 再低，瓦特封顶则要降 \\(f\\) 或关单元。验证测试向量的高翻转会超过功能 TDP，需要分模式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导短沟道效应全套方程，不预测某年之后的节点名。不把大模型训练集群的 MW 当成 Dennard 的反例展开。不进入光刻能否成像更小栅——那是光刻栏。</p><p>后课默认：Dennard 缩放已破，功耗密度限制同时点亮的逻辑；频率不是免费礼物。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Dennard：尺寸与电压同降，功耗密度近似不变。</li><li>墙：\\(V\\) 与漏电，频率停，暗硅出现。</li><li>门控/DVFS/专用单元是墙后的工程回答。</li><li>出处：Dennard et al., <em>IEEE JSSC</em>, 1974；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const P=d(A,[["render",c]]);export{u as __pageData,P as default};
